};

const getLink = (item) => {
  if (item.link) return item.link;
  if (item.href) {
    return {
      href: item.href,
      text: item.linkText || item.cta || "Learn more",
    };
  }
  return null;
};

const renderStickyContent = (item) => {
  const paragraphs = getParagraphs(item);
  const listItems = getListItems(item);
